"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[70969],{33609:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>u,frontMatter:()=>o,metadata:()=>i,toc:()=>d});var h=n(31085),a=n(71184);const o={sidebar_position:14,slug:"/bible/1_Kings/1_Kings_14",title:"1 Kings 14",hide_table_of_contents:!0},s="1 Kings",i={id:"bible/1 Kings/1 Kings 14",title:"1 Kings 14",description:"Chapter 14",source:"@site/docs/bible/1 Kings/1 Kings 14.md",sourceDirName:"bible/1 Kings",slug:"/bible/1_Kings/1_Kings_14",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_14",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Kings/1 Kings 14.md",tags:[],version:"current",sidebarPosition:14,frontMatter:{sidebar_position:14,slug:"/bible/1_Kings/1_Kings_14",title:"1 Kings 14",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Kings 13",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_13"},next:{title:"1 Kings 15",permalink:"/bibleNotes/docs/bible/1_Kings/1_Kings_15"}},r={},d=[{value:"Chapter 14",id:"chapter-14",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,a.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"1-kings",children:"1 Kings"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-14",children:"Chapter 14"}),"\n",(0,h.jsx)(t.p,{children:"Jonathan attacketh the Philistines.  A miraculous victory.  Saul's unadvised oath, by which Jonathan is put in danger of his life, but is delivered by the people."}),"\n",(0,h.jsx)(n,{verse:1,children:"Now it came to pass one day that Jonathan, the son of Saul, said to the young man that bore his armour: Come, and let us go over to the garrison of the Philistines, which is on the other side of yonder place. But he told not this to his father."}),"\n",(0,h.jsx)(n,{verse:2,children:"And Saul abode in the uttermost part of Gabaa, under the pomegranate tree, which was in Magron: and the people with him were about six hundred men."}),"\n",(0,h.jsx)(n,{verse:3,children:"And Achias, the son of Achitob, brother of Ichabod the son of Phinees, the son of Heli, the priest of the Lord in Silo, wore the ephod. And the people knew not whither Jonathan was gone."}),"\n",(0,h.jsx)(n,{verse:4,children:"Now there were between the ascents, by which Jonathan sought to go over to the garrison of the Philistines, rocks standing up on both sides, and steep cliffs like teeth on the one side, and on the other, the name of the one was Boses, and the name of the other was Sene:"}),"\n",(0,h.jsx)(n,{verse:5,children:"One rock stood out toward the north, over against Machmas, and the other to the south, over against Gabaa."}),"\n",(0,h.jsx)(n,{verse:6,children:"And Jonathan said to the young man that bore his armour: Come, let us go over to the garrison of these uncircumcised, it may be the Lord will do for us: because it is easy for the Lord to save either by many, or by few."}),"\n",(0,h.jsx)(n,{verse:7,children:"And his armourbearer said to him: Do all that pleaseth thy mind: go whither thou wilt, and I will be with thee wheresoever thou hast a mind."}),"\n",(0,h.jsx)(n,{verse:8,children:"And Jonathan said: Behold we will go over to these men. And when we shall be seen by them,"}),"\n",(0,h.jsx)(n,{verse:9,children:"If they shall speak thus to us: Stay till we come to you: let us stand still in our place, and not go up to them."}),"\n",(0,h.jsx)(n,{verse:10,children:"But if they shall say: Come up to us: let us go up, because the Lord hath delivered them into our hands, this shall be a sign unto us."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: This shall be a sign...It is likely Jonathan was instructed by divine inspiration to make a choice of this sign: otherwise the observation of omens is superstitious and sinful."})}),"\n",(0,h.jsx)(n,{verse:11,children:"So both of them discovered themselves to the garrison of the Philistines: and the Philistines said: Behold the Hebrews come forth out of the holes wherein they were hid."}),"\n",(0,h.jsx)(n,{verse:12,children:"And the men of the garrison spoke to Jonathan, and to his armourbearer, and said: Come up to us, and we will shew you a thing. And Jonathan said to his armourbearer: Let us go up, follow me: for the Lord hath delivered them into the hands of Israel."}),"\n",(0,h.jsx)(n,{verse:13,children:"And Jonathan went up creeping on his hands and feet, and his armourbearer after him. And some fell before Jonathan, others his armourbearer slew as he followed him."}),"\n",(0,h.jsx)(n,{verse:14,children:"And the first slaughter which Jonathan and his armourbearer made, was of about twenty men, within half an acre of land, which a yoke of oxen is wont to plough in a day."}),"\n",(0,h.jsx)(n,{verse:15,children:"And there was a miracle in the camp, in the fields: and all the people of their garrison, who had gone out to plunder, were amazed, and the earth trembled: and it happened as a miracle from God."}),"\n",(0,h.jsx)(n,{verse:16,children:"And the watchmen of Saul, who were in Gabaa of Benjamin looked, and behold a multitude overthrown, and fleeing this way and that."}),"\n",(0,h.jsx)(n,{verse:17,children:"And Saul said to the people that were with him: Look, and see who is gone from us. And when they had sought, it was found that Jonathan and his armourbearer were not there."}),"\n",(0,h.jsx)(n,{verse:18,children:"And Saul said to Achias: Bring the ark of the Lord. (For the ark of God was there that day with the children of Israel.)"}),"\n",(0,h.jsx)(n,{verse:19,children:"And while Saul spoke to the priest, there arose a great uproar in the camp of the Philistines: and it increased by degrees, and was heard more clearly. And Saul said to the priest: Draw in thy hand."}),"\n",(0,h.jsx)(n,{verse:20,children:"Then Saul, and all the people that were with him, shouted together, and they came to the place of the fight: and behold every man's sword was turned upon his neighbour, and there was a very great slaughter."}),"\n",(0,h.jsx)(n,{verse:21,children:"Moreover, the Hebrews that had been with the Philistines yesterday and the day before, and went up with them into the camp, returned to be with the Israelites, who were with Saul and Jonathan."}),"\n",(0,h.jsx)(n,{verse:22,children:"And all the Israelites that had hid themselves in mount Ephraim, hearing that the Philistines fled, joined themselves with their countrymen in the fight. And there were with Saul about ten thousand men."}),"\n",(0,h.jsx)(n,{verse:23,children:"And the Lord saved Israel that day. And the fight went on as far as Bethaven."}),"\n",(0,h.jsx)(n,{verse:24,children:"And the men of Israel were joined together that day: and Saul adjured the people, saying: Cursed be the man that shall eat food till evening, till I be revenged of my enemies. So none of the people tasted any food."}),"\n",(0,h.jsx)(n,{verse:25,children:"And all the common people came into a forest, in which there was honey upon the ground."}),"\n",(0,h.jsx)(n,{verse:26,children:"And when the people came into the forest, behold the honey dropped, but no man put his hand to his mouth. For the people feared the oath."}),"\n",(0,h.jsx)(n,{verse:27,children:"But Jonathan had not heard when his father adjured the people: and he put forth the end of the rod, which he had in his hand, and dipt it in a honeycomb: and he carried his hand to his mouth, and his eyes were enlightened."}),"\n",(0,h.jsx)(n,{verse:28,children:"And one of the people answering, said: Thy father hath bound the people with an oath, saying: Cursed be the man that shall eat any food this day. (And the people were faint.)"}),"\n",(0,h.jsx)(n,{verse:29,children:"And Jonathan said: My father hath troubled the land: you have seen yourselves that my eyes are enlightened, because I tasted a little of this honey:"}),"\n",(0,h.jsx)(n,{verse:30,children:"How much more if the people had eaten of the prey of their enemies, which they found? had there not been made a greater slaughter among the Philistines?"}),"\n",(0,h.jsx)(n,{verse:31,children:"So they smote that day the Philistines, from Machmas to Aialon. And the people were wearied exceedingly."}),"\n",(0,h.jsx)(n,{verse:32,children:"And falling upon the spoils, they took sheep, and oxen, and calves, and slew them on the ground: and the people ate them with the blood."}),"\n",(0,h.jsx)(n,{verse:33,children:"And they told Saul that the people had sinned against the Lord, eating with the blood. And he said: You have transgressed: roll here to me now a great stone."}),"\n",(0,h.jsx)(n,{verse:34,children:"And Saul said: Disperse yourselves among the people, and tell them to bring me every man his ox and his ram and slay them upon this stone, and eat, and you shall not sin against the Lord, in eating with the blood. So all the people brought every man his ox with him till the night: and slew them there."}),"\n",(0,h.jsx)(n,{verse:35,children:"And Saul built an altar to the Lord: and he then first began to build an altar to the Lord."}),"\n",(0,h.jsx)(n,{verse:36,children:"And Saul said: Let us fall upon the Philistines by night, and destroy them till the morning light, and let us not leave a man of them. And the people said: Do all that seemeth good in thy eyes. And the priest said: Let us draw near hither unto God."}),"\n",(0,h.jsx)(n,{verse:37,children:"And Saul consulted the Lord: Shall I pursue after the Philistines? wilt thou deliver them into the hands of Israel? And he answered him not that day."}),"\n",(0,h.jsx)(n,{verse:38,children:"And Saul said: Bring hither all the corners of the people: and know, and see by whom this sin hath happened to day."}),"\n",(0,h.jsx)(n,{verse:39,children:"As the Lord liveth, who is the Saviour of Israel, if it was done by Jonathan, my son, he shall surely die. In this none of the people gainsayed him."}),"\n",(0,h.jsx)(n,{verse:40,children:"And he said to all Israel: Be you on one side and I, with Jonathan, my son, will be on the other side. And the people answered Saul: Do what seemeth good in thy eyes."}),"\n",(0,h.jsx)(n,{verse:41,children:"And Saul said to the Lord: O Lord God of Israel, give a sign, by which we may know, what the meaning is, that thou answerest not thy servant to day: If this iniquity be in me, or in my son Jonathan, give a proof: or if this iniquity be in thy people, give holiness. And Jonathan and Saul were taken, and the people escaped."}),"\n",(0,h.jsx)(n,{verse:42,children:"And Saul said: (Cast lots between me, and Jonathan, my son. And Jonathan was taken."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Jonathan was taken...Though Jonathan was excused from sin, through ignorance of the prohibition, yet God was pleased on this occasion to let the lot fall upon him, to shew unto all the great obligation of obedience to princes and parents."})}),"\n",(0,h.jsx)(n,{verse:43,children:"And Saul said to Jonathan: Tell me what thou hast done. And Jonathan told him, and said: I did but taste a little honey with the end of the rod, which was in my hand, and behold I must die."}),"\n",(0,h.jsx)(n,{verse:44,children:"And Saul said: May God do so and so to me, and add still more: for dying thou shalt die, O Jonathan."}),"\n",(0,h.jsx)(n,{verse:45,children:"And the people said to Saul: Shall Jonathan then die, who hath wrought this great salvation in Israel? this must not be: As the Lord liveth, there shall not one hair of his head fall to the ground, for he hath wrought with God this day. So the people delivered Jonathan, that he should not die."}),"\n",(0,h.jsx)(n,{verse:46,children:"And Saul went back, and did not pursue after the Philistines: and the Philistines went to their own places."}),"\n",(0,h.jsx)(n,{verse:47,children:"And Saul having his kingdom established over Israel, fought against all his enemies round about, against Moab, and against the children of Ammon, and Edom, and the kings of Soba, and the Philistines: and whithersoever he turned himself, he overcame."}),"\n",(0,h.jsx)(n,{verse:48,children:"And gathering together an army, he defeated Amalec, and delivered Israel from the hand of them that spoiled them."}),"\n",(0,h.jsx)(n,{verse:49,children:"And the sons of Saul, were Jonathan, and Jessui, and Melchisua: and the names of his two daughters, the name of the firstborn was Merob, and the name of the younger Michol."}),"\n",(0,h.jsx)(n,{verse:50,children:"And the name of Saul's wife was Achinoam, the daughter of Achimaas; and the name of the captain of his army was Abner, the son of Ner, the cousin german of Saul."}),"\n",(0,h.jsx)(n,{verse:51,children:"For Cis was the father of Saul, and Ner, the father of Abner, was son of Abiel."}),"\n",(0,h.jsx)(n,{verse:52,children:"And there was a great war against the Philistines all the days of Saul. For whomsoever Saul saw to be a valiant man, and fit for war, he took him to himself."})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>i});var h=n(14041);const a={},o=h.createContext(a);function s(e){const t=h.useContext(o);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),h.createElement(o.Provider,{value:t},e.children)}}}]);